import { describe, expect, it, vi } from "vitest";

// dist/wasm/movi.js is generated by build:wasm (Docker/4090) and is absent in
// the unit-test CI job (dist/ is gitignored). Demuxer's module graph imports it
// eagerly via FFmpegLoader; this test never loads/runs the WASM, so stub the
// module so importing Demuxer resolves without the built artifact.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));

import { Demuxer } from "../../src/demux/Demuxer";

function createOpenedDemuxer() {
  // A real instance, not Object.create(prototype): the constructor is what
  // initialises the field that serializes WASM entry points, and a prototype-
  // only object skips it. The constructor itself only stores its arguments, so
  // the source below is never touched by seek().
  const demuxer = new Demuxer({} as never) as Demuxer & {
    bindings: { seek: ReturnType<typeof vi.fn> };
    isOpened: boolean;
  };
  demuxer.bindings = {
    seek: vi.fn().mockResolvedValue(undefined),
  };
  demuxer.isOpened = true;
  return demuxer;
}

describe("Demuxer.seek", () => {
  it("passes the requested stream index through to the WASM binding", async () => {
    const demuxer = createOpenedDemuxer();

    await demuxer.seek(306.882, 1, 3);

    expect(demuxer.bindings.seek).toHaveBeenCalledWith(306.882, 3, 1);
  });

  it("keeps global seek as the default for callers that do not choose a stream", async () => {
    const demuxer = createOpenedDemuxer();

    await demuxer.seek(12.5);

    expect(demuxer.bindings.seek).toHaveBeenCalledWith(12.5, -1, 1);
  });
});
